using System;
using System.Data;
using System.Globalization;
using System.Web.UI;
using TKSObject;

namespace InformationWeb.Controls.Employee_V2
{
    /// <summary>
    /// Tab phụ cấp hợp đồng — chỉ xem.
    /// </summary>
    public partial class TabPhuCapHD : UserControl
    {
        private const string StoreContractSubForEmployee = "HRS_ContractSub_SearchForEmployee";

        private readonly HRS_Employee employeeDao = new HRS_Employee();

        protected void Page_Load(object sender, EventArgs e)
        {
        }

        public void BindForEmployee(long employeeId)
        {
            DataTable dt = null;
            try
            {
                dt = employeeDao.GetDataTable(StoreContractSubForEmployee, "@EmployeeID", employeeId);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabPhuCapHD.BindForEmployee: " + ex.Message);
            }

            if (dt == null)
                dt = new DataTable();

            gvPhuCapHD.DataSource = dt;
            gvPhuCapHD.DataBind();
        }

        protected string FormatDecimal(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            decimal d;
            if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
            {
                if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
                    return value.ToString();
            }
            return d.ToString("N2", CultureInfo.InvariantCulture);
        }

        protected string IsActivedCss(object value)
        {
            bool active = false;
            if (value != null && value != DBNull.Value)
            {
                if (value is bool)
                    active = (bool)value;
                else
                {
                    string s = value.ToString().Trim();
                    active = s == "1" || string.Equals(s, "true", StringComparison.OrdinalIgnoreCase);
                }
            }
            if (active)
                return "bi bi-check-square-fill text-success";
            return "bi bi-square text-muted";
        }
    }
}

