        private void ApplyActiveTabUi(string tabKey, bool reloadViewTabData)
        {
            bool isLyLich = tabKey == TabLyLichKey;
            bool isQuaTrinhLuong = tabKey == TabQuaTrinhLuongKey;
            bool isPhuCapHD = tabKey == TabPhuCapHDKey;
            bool isNhaGiao = tabKey == TabNhaGiaoKey;

            if (!isLyLich && !isQuaTrinhLuong && !isPhuCapHD && !isNhaGiao)
            {
                isLyLich = true;
                tabKey = TabLyLichKey;
                hidActiveTab.Value = tabKey;
                isQuaTrinhLuong = false;
                isPhuCapHD = false;
                isNhaGiao = false;
            }

            pnlTabLyLich.Visible = isLyLich;
            pnlTabQuaTrinhLuong.Visible = isQuaTrinhLuong;
            pnlTabPhuCapHD.Visible = isPhuCapHD;
            pnlTabNhaGiao.Visible = isNhaGiao;

            SetTabNavActive(btnTabLyLich, isLyLich);
            SetTabNavActive(btnTabQuaTrinhLuong, isQuaTrinhLuong);
            SetTabNavActive(btnTabPhuCapHD, isPhuCapHD);
            SetTabNavActive(btnTabNhaGiao, isNhaGiao);

            SetActionButtonsVisible(isLyLich);

            if (reloadViewTabData)
            {
                if (isQuaTrinhLuong)
                    LoadQuaTrinhLuongTab();
                else if (isPhuCapHD)
                    LoadPhuCapHDTab();
                else if (isNhaGiao)
                    LoadNhaGiaoTab();
            }
        }

